const fs = require('fs');
const path = require('path');
const dashboardInventory = require('./dashboard-inventory');

/**
 * Inventories of the shipped template trees — one `inventory.json` at the root
 * of each tree, generated by `tools/templates/inventory.mjs --kind <kind>`
 * (`--write`, `--check`) and shipped with every release:
 *
 *   dashboards/inventory.json   see dashboard-inventory.js
 *   queries/inventory.json      { version: 1,
 *                                 queries: [ { name, path, area }, … ],
 *                                 folders: [ path, … ] }
 *   tests/inventory.json        { version: 1,
 *                                 tests: [ { id, path }, … ],
 *                                 folders: [ path, … ] }
 *
 * Paths are relative to the tree root and sorted, so the files are stable and
 * diffs stay small. The queries tree holds the internal templates only: a
 * query's `path` is its file (`system/graph/graph_nodes.sql`), its `area` the
 * storage area of the first segment (`system`, `module`). Content queries are
 * single-file dashboards and live in the dashboard inventory. A test's `path`
 * is its directory (`script/script-todos`). `folders` lists every other
 * directory of the tree.
 *
 * At runtime an inventory answers "what does this release ship" without
 * `.git` (Docker and ZIP installations have none): the dashboard discovery
 * reads the old query location only for names outside the dashboard and the
 * query inventory, and the cleanup routines tell leftovers apart from shipped
 * content.
 */

const INVENTORY_FILE = 'inventory.json';
const FORMAT_VERSION = 1;
// Safety net against symlink loops; the shipped trees are far shallower.
const MAX_DEPTH = 8;
const KINDS = ['dashboards', 'queries', 'tests'];

// First path segment of the shipped query tree → storage area.
const QUERY_GROUP_AREAS = { system: 'system', modules: 'module' };

function byPath(a, b) {
  return a.path < b.path ? -1 : a.path > b.path ? 1 : 0;
}

function readDirSafe(abs) {
  try {
    return fs.readdirSync(abs, { withFileTypes: true });
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

function queryArea(relPath) {
  const segs = relPath.split('/');
  return (segs.length > 1 && QUERY_GROUP_AREAS[segs[0]]) || 'builtin';
}

function buildQueriesInventory(queriesDir) {
  const queries = [];
  const folders = [];
  const walk = (rel, depth) => {
    for (const e of readDirSafe(path.join(queriesDir, rel))) {
      if (e.name.startsWith('.')) continue;
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory()) {
        folders.push(childRel);
        if (depth < MAX_DEPTH) walk(childRel, depth + 1);
      } else if (e.isFile() && e.name.endsWith('.sql')) {
        queries.push({ name: e.name.slice(0, -4), path: childRel, area: queryArea(childRel) });
      }
    }
  };
  walk('', 0);
  queries.sort(byPath);
  folders.sort();
  return { version: FORMAT_VERSION, queries, folders };
}

function buildTestsInventory(testsDir) {
  const tests = [];
  const folders = [];
  const walk = (rel, depth) => {
    for (const e of readDirSafe(path.join(testsDir, rel))) {
      if (!e.isDirectory() || e.name.startsWith('.')) continue;
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      let isTest = false;
      try {
        isTest = fs.statSync(path.join(testsDir, childRel, 'test.json')).isFile();
      } catch {
        // folder without test.json
      }
      if (isTest) {
        tests.push({ id: e.name, path: childRel });
      } else {
        folders.push(childRel);
        if (depth < MAX_DEPTH) walk(childRel, depth + 1);
      }
    }
  };
  walk('', 0);
  tests.sort(byPath);
  folders.sort();
  return { version: FORMAT_VERSION, tests, folders };
}

function assertKind(kind) {
  if (!KINDS.includes(kind)) throw new Error(`Unknown inventory kind: ${kind}`);
}

/** Walks the tree of `kind` under `dir` and returns its inventory (not written). */
function buildInventory(kind, dir) {
  assertKind(kind);
  if (kind === 'dashboards') return dashboardInventory.buildInventory(dir);
  if (kind === 'queries') return buildQueriesInventory(dir);
  return buildTestsInventory(dir);
}

/** Serialized form, byte-stable for `--check`. */
function serializeInventory(inventory) {
  return JSON.stringify(inventory, null, 2) + '\n';
}

function inventoryPath(dir) {
  return path.join(dir, INVENTORY_FILE);
}

/**
 * Reads the inventory of `kind` from `dir`. Returns null when the file is
 * missing or unusable — callers must then treat the tree as unknown, never as
 * empty.
 */
function readInventory(kind, dir) {
  assertKind(kind);
  if (kind === 'dashboards') return dashboardInventory.readInventory(dir);
  let parsed;
  try {
    parsed = JSON.parse(fs.readFileSync(inventoryPath(dir), 'utf-8'));
  } catch {
    return null;
  }
  if (!parsed || !Array.isArray(parsed.folders)) return null;
  const folders = parsed.folders.filter(f => typeof f === 'string');
  if (kind === 'queries') {
    if (!Array.isArray(parsed.queries)) return null;
    return {
      version: parsed.version,
      queries: parsed.queries.filter(q => q && typeof q.name === 'string' && typeof q.path === 'string'),
      folders,
    };
  }
  if (!Array.isArray(parsed.tests)) return null;
  return {
    version: parsed.version,
    tests: parsed.tests.filter(t => t && typeof t.id === 'string' && typeof t.path === 'string'),
    folders,
  };
}

/**
 * Differences between two inventories of `kind` as human-readable lines
 * (`+ query top/top_scripts.sql`, `- folder layouts`); empty when equal.
 */
function diffInventories(kind, expected, actual) {
  assertKind(kind);
  if (kind === 'dashboards') return dashboardInventory.diffInventories(expected, actual);
  const [label, list, key] = kind === 'queries'
    ? ['query', 'queries', q => `${q.path}\t${q.name}\t${q.area}`]
    : ['test', 'tests', t => `${t.path}\t${t.id}`];
  const lines = [];
  const diffSets = (what, exp, act) => {
    const e = new Set(exp);
    const a = new Set(act);
    for (const x of a) if (!e.has(x)) lines.push(`+ ${what} ${x.split('\t')[0]}`);
    for (const x of e) if (!a.has(x)) lines.push(`- ${what} ${x.split('\t')[0]}`);
  };
  diffSets(label, expected[list].map(key), actual[list].map(key));
  diffSets('folder', expected.folders, actual.folders);
  return lines.sort();
}

/** Number of units and folders, for tool output. */
function describeInventory(kind, inventory) {
  if (kind === 'dashboards') {
    const files = inventory.bundles.filter(b => b.unit === 'file').length;
    return `${inventory.bundles.length - files} bundles, ${files} single-file dashboards, ${inventory.folders.length} folders`;
  }
  return `${inventory[kind].length} ${kind}, ${inventory.folders.length} folders`;
}

module.exports = {
  INVENTORY_FILE,
  FORMAT_VERSION,
  KINDS,
  buildInventory,
  serializeInventory,
  inventoryPath,
  readInventory,
  diffInventories,
  describeInventory,
};
